def hcf(a, b):
    h = 1
    i = 1
    while i <= a and i <= b:
        if a % i == 0 and b % i == 0:
            h = i
        i = i + 1
    return h

def lcm(a, b):
    l = max(a, b)
    while not (l % a == 0 and l % b == 0):
        l = l + 1
    return l

def stats(num, bound):
    total = 0
    largest = num[0]
    smallest = num[0]
    count = 0
