pr.solution:
def delete_at(num, P):
    N = len(num)
    for i in range(P, N - 1):
        num[i] = num[i + 1]
    num[N - 1] = 0
    return num

def insert_at(num, P, x):
    num = num + [0]
    N = len(num)
    for i in range(N - 1, P, -1):
        num[i] = num[i - 1]
    num[P] = x
    return num

