def balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if len(stack) == 0 or stack.pop() != pairs[ch]:
                return False
    return len(stack) == 0

def editor(cmds):
    undo = []
    redo = []
    for c in cmds:
        if c == 'UNDO':
            if undo:
                redo.append(undo.pop())
        elif c == 'REDO':
            if redo:
                undo.append(redo.pop())
        else:
            undo.append(c)
            redo = []
    return undo

def remove_bottom(s1, n):
    s2 = []
    while s1:
        s2.append(s1.pop())
    for i in range(n):
        s2.pop()
    while s2:
        s1.append(s2.pop())
    return s1

